templates.template:
/* Кордон — гражданский стиль XenForo 2.2 / 2.3
   Память и профилактика. Не сайт государственного органа.
   Правьте строку выпуска в .p-header::before и подзаголовок в .p-header-content::after. */



/* KORDON-DARK-START */
:root {
  --k-bg: #121a28;
  --k-surface: #182232;
  --k-surface-2: #1c283b;
  --k-offset: #243044;
  --k-ink: #f4f0e8;
  --k-muted: #c5cdd8;
  --k-faint: #aeb6c2;
  --k-line: #3a465c;
  --k-navy: #0c1422;
  --k-navy-2: #1b2940;
  --k-signal: #861f32;
  --k-signal-ink: #a83248;
  --k-link: #f0c2cc;
  --k-link-hover: #fffdfa;
  --k-bronze: #e0c48a;
  --k-olive: #9db8aa;
  --k-on-signal: #fffdfa;
  --k-on-navy: #f4f0e8;
  --k-footer: #0b101a;
  --k-footer-link: #f0d7a6;
  --k-header: #161f30;
  color-scheme: dark;
}
/* KORDON-DARK-END */

@font-face {
  font-family: "Manrope";
  font-style: normal;
  font-weight: 200 800;
  font-display: swap;
  src: url("{{ asset('kordon') }}/fonts/manrope-cyrillic.woff2") format("woff2");
  unicode-range: U+0301, U+0400-045F, U+0490-0491, U+04B0-04B1, U+2116;
}
@font-face {
  font-family: "Manrope";
  font-style: normal;
  font-weight: 200 800;
  font-display: swap;
  src: url("{{ asset('kordon') }}/fonts/manrope-latin.woff2") format("woff2");
  unicode-range: U+0000-00FF, U+0131, U+0152-0153, U+02BB-02BC, U+02C6, U+02DA, U+02DC, U+0304, U+0308, U+0329, U+2000-206F, U+20AC, U+2122, U+2191, U+2193, U+2212, U+2215, U+FEFF, U+FFFD;
}
@font-face {
  font-family: "Source Serif 4";
  font-style: normal;
  font-weight: 200 900;
  font-display: swap;
  src: url("{{ asset('kordon') }}/fonts/source-serif-4-cyrillic.woff2") format("woff2");
  unicode-range: U+0301, U+0400-045F, U+0490-0491, U+04B0-04B1, U+2116;
}
@font-face {
  font-family: "Source Serif 4";
  font-style: normal;
  font-weight: 200 900;
  font-display: swap;
  src: url("{{ asset('kordon') }}/fonts/source-serif-4-latin.woff2") format("woff2");
  unicode-range: U+0000-00FF, U+0131, U+0152-0153, U+02BB-02BC, U+02C6, U+02DA, U+02DC, U+0304, U+0308, U+0329, U+2000-206F, U+20AC, U+2122, U+2191, U+2193, U+2212, U+2215, U+FEFF, U+FFFD;
}
@font-face {
  font-family: "IBM Plex Mono";
  font-style: normal;
  font-weight: 400;
  font-display: swap;
  src: url("{{ asset('kordon') }}/fonts/ibm-plex-mono-cyrillic-400.woff2") format("woff2");
  unicode-range: U+0301, U+0400-045F, U+0490-0491, U+04B0-04B1, U+2116;
}
@font-face {
  font-family: "IBM Plex Mono";
  font-style: normal;
  font-weight: 400;
  font-display: swap;
  src: url("{{ asset('kordon') }}/fonts/ibm-plex-mono-latin-400.woff2") format("woff2");
  unicode-range: U+0000-00FF, U+0131, U+0152-0153, U+02BB-02BC, U+02C6, U+02DA, U+02DC, U+0304, U+0308, U+0329, U+2000-206F, U+20AC, U+2122, U+2191, U+2193, U+2212, U+2215, U+FEFF, U+FFFD;
}
@font-face {
  font-family: "IBM Plex Mono";
  font-style: normal;
  font-weight: 500;
  font-display: swap;
  src: url("{{ asset('kordon') }}/fonts/ibm-plex-mono-cyrillic-500.woff2") format("woff2");
  unicode-range: U+0301, U+0400-045F, U+0490-0491, U+04B0-04B1, U+2116;
}
@font-face {
  font-family: "IBM Plex Mono";
  font-style: normal;
  font-weight: 500;
  font-display: swap;
  src: url("{{ asset('kordon') }}/fonts/ibm-plex-mono-latin-500.woff2") format("woff2");
  unicode-range: U+0000-00FF, U+0131, U+0152-0153, U+02BB-02BC, U+02C6, U+02DA, U+02DC, U+0304, U+0308, U+0329, U+2000-206F, U+20AC, U+2122, U+2191, U+2193, U+2212, U+2215, U+FEFF, U+FFFD;
}

html {
  background: var(--k-bg);
}

body {
  margin: 0;
  background: var(--k-bg);
  color: var(--k-ink);
  border-top: 3px solid var(--k-signal);
  font-family: var(--k-body), "Segoe UI", "Helvetica Neue", Arial, sans-serif;
  font-size: 15px;
  line-height: 1.6;
  text-rendering: optimizeLegibility;
}

body::before {
  content: "";
  position: fixed;
  inset: 0;
  pointer-events: none;
  z-index: 30;
  opacity: 0.14;
  background-image: url("{{ asset('kordon') }}/grain.svg");
  mix-blend-mode: multiply;
}

:root body::before {
  opacity: 0.1;
  mix-blend-mode: overlay;
}

::selection {
  background: #861f3233;
  color: var(--k-ink);
}

:root ::selection {
  background: #f0c2cc33;
}

:focus-visible {
  outline: 2px solid var(--k-signal);
  outline-offset: 3px;
}

a {
  color: var(--k-link);
  text-decoration-thickness: 1px;
  text-underline-offset: 3px;
}

a:hover {
  color: var(--k-link-hover);
}

h1, h2, h3, .p-title-value, .node-title, .structItem-title, .block--category .block-header, .message-name {
  font-family: var(--k-display), "Iowan Old Style", Palatino, "Palatino Linotype", Georgia, serif;
  font-weight: 600;
  letter-spacing: -0.03em;
}

/* Header */

.p-header {
  background: var(--k-header);
  color: var(--k-ink);
  border-bottom: 1px solid var(--k-line);
}

.p-header::before {
  content: "Кордон  ·  независимый форум  ·  при угрозе — 112";
  display: block;
  box-sizing: border-box;
  max-width: 1180px;
  margin: 0 auto;
  padding: 9px 20px 8px;
  border-bottom: 1px solid var(--k-line);
  color: var(--k-muted);
  font-family: var(--k-mono), ui-monospace, monospace;
  font-size: 11px;
  font-weight: 500;
  letter-spacing: 0.08em;
  line-height: 1.45;
  text-transform: uppercase;
}

.p-header-inner,
.p-nav-inner,
.p-sectionLinks-inner,
.p-body-inner,
.p-footer-inner,
.p-staffBar-inner {
  box-sizing: border-box;
  width: 100%;
  max-width: 1180px;
  margin: 0 auto;
  padding-left: 20px;
  padding-right: 20px;
}

.p-header-inner {
  padding-top: 18px;
  padding-bottom: 16px;
}

.p-header-logo--text a,
.p-header-logo--image a {
  display: inline-flex;
  align-items: center;
  gap: 12px;
  color: var(--k-ink);
  text-decoration: none;
  font-family: var(--k-display), Georgia, serif;
  font-weight: 600;
  font-size: 34px;
  letter-spacing: -0.045em;
  line-height: 1;
}

.p-header-logo--text a:hover,
.p-header-logo--image a:hover {
  color: var(--k-ink);
}

.p-header-logo--text a::before {
  content: "";
  width: 42px;
  height: 42px;
  flex: 0 0 auto;
  background: url("{{ asset('kordon') }}/mark.svg") center / contain no-repeat;
}

:root .p-header-logo--text a::before {
  background-image: url("{{ asset('kordon') }}/mark-dark.svg");
}

.p-header-content::after {
  content: "память и профилактика";
  display: block;
  margin: 7px 0 2px 54px;
  color: var(--k-bronze);
  font-family: var(--k-mono), ui-monospace, monospace;
  font-size: 11px;
  font-weight: 500;
  letter-spacing: 0.14em;
  text-transform: uppercase;
}

.p-nav {
  background: var(--k-navy);
  color: var(--k-on-navy);
  border-bottom: 0;
}

.p-nav-inner {
  min-height: 54px;
  display: flex;
  align-items: center;
  gap: 12px;
}

.p-nav a,
.p-nav a:hover,
.p-nav-list .p-navEl-link,
.p-nav-list .p-navEl-link:hover,
.p-navgroup-link,
.p-navgroup-link:hover {
  color: var(--k-on-navy);
  text-decoration: none;
}

.p-nav-list .p-navEl-link {
  font-size: 14.5px;
  font-weight: 650;
  letter-spacing: 0.01em;
  padding: 16px 12px;
  box-shadow: inset 0 0 0 transparent;
}

.p-nav-list .p-navEl-link:hover,
.p-nav-list .p-navEl.is-selected .p-navEl-link {
  background: transparent;
  box-shadow: inset 0 -2px 0 var(--k-signal);
}

.p-nav-smallLogo a {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  color: var(--k-on-navy);
  font-family: var(--k-display), Georgia, serif;
  font-size: 20px;
  text-decoration: none;
}

.p-nav-smallLogo a::before {
  content: "";
  width: 22px;
  height: 22px;
  background: url("{{ asset('kordon') }}/mark-dark.svg") center / contain no-repeat;
}

.p-navgroup-link {
  border-radius: 2px;
  padding: 6px 8px;
}

.p-navgroup-link:hover {
  background: #ffffff14;
}

.p-nav-menuTrigger {
  color: var(--k-on-navy);
  border: 1px solid #f4f0e833;
  border-radius: 2px;
}

.p-sectionLinks {
  background: var(--k-bg);
  border-bottom: 1px solid var(--k-line);
  color: var(--k-muted);
}

.p-sectionLinks-inner {
  min-height: 40px;
  display: flex;
  align-items: center;
}

.p-sectionLinks a,
.p-sectionLinks-link {
  color: var(--k-muted);
  text-decoration: none;
  font-size: 13px;
  font-weight: 650;
}

.p-sectionLinks a:hover,
.p-sectionLinks a.is-selected,
.p-sectionLinks-link.is-selected {
  color: var(--k-ink);
}

.p-staffBar {
  background: var(--k-navy-2);
  color: var(--k-on-navy);
  font-size: 12.5px;
}

.p-staffBar a,
.p-staffBar a:hover {
  color: var(--k-footer-link);
}

/* Page */

.p-pageWrapper {
  min-height: 100vh;
  display: flex;
  flex-direction: column;
}

.p-body {
  flex: 1 0 auto;
  background: transparent;
  color: var(--k-ink);
}

.p-body-inner {
  padding-top: 26px;
  padding-bottom: 56px;
}

.p-breadcrumbs {
  display: flex;
  flex-wrap: wrap;
  gap: 6px 0;
  margin: 0 0 16px;
  padding: 0;
  list-style: none;
  font-family: var(--k-mono), ui-monospace, monospace;
  font-size: 11px;
  letter-spacing: 0.06em;
  text-transform: uppercase;
}

.p-breadcrumbs a {
  color: var(--k-muted);
  text-decoration: none;
}

.p-breadcrumbs a:hover {
  color: var(--k-link);
}

.p-breadcrumbs > li + li::before {
  content: "/";
  margin: 0 8px;
  color: var(--k-faint);
}

.p-title {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: 16px;
  margin: 0 0 8px;
}

.p-title-value {
  margin: 0;
  font-size: 40px;
  line-height: 1.05;
  color: var(--k-ink);
}

.p-description {
  margin: 0 0 18px;
  max-width: 68ch;
  color: var(--k-muted);
  font-size: 16px;
}

/* Buttons, labels, forms */

.button,
a.button {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  box-sizing: border-box;
  min-height: 38px;
  padding: 0 14px;
  border: 1px solid var(--k-line);
  border-radius: 2px;
  background: var(--k-surface-2);
  color: var(--k-ink);
  font-family: var(--k-body), Arial, sans-serif;
  font-size: 14px;
  font-weight: 700;
  letter-spacing: 0.01em;
  line-height: 1;
  text-decoration: none;
  box-shadow: none;
}

.button:hover,
a.button:hover {
  background: var(--k-offset);
  color: var(--k-ink);
  text-decoration: none;
}

.button.button--primary,
.button.button--cta,
a.button.button--primary,
a.button.button--cta {
  background: var(--k-signal);
  border-color: var(--k-signal);
  color: var(--k-on-signal);
}

.button.button--primary:hover,
.button.button--cta:hover,
a.button.button--primary:hover,
a.button.button--cta:hover {
  background: var(--k-signal-ink);
  border-color: var(--k-signal-ink);
  color: var(--k-on-signal);
}

.button.button--link,
a.button.button--link {
  background: transparent;
  border-color: transparent;
  color: var(--k-link);
}

.button.button--link:hover,
a.button.button--link:hover {
  background: var(--k-offset);
  color: var(--k-link-hover);
}

.label,
.labelLink {
  display: inline-block;
  margin-right: 6px;
  padding: 2px 6px 1px;
  border: 1px solid var(--k-line);
  border-radius: 2px;
  background: transparent;
  color: var(--k-bronze);
  font-family: var(--k-mono), ui-monospace, monospace;
  font-size: 10px;
  font-weight: 500;
  letter-spacing: 0.08em;
  line-height: 1.4;
  text-transform: uppercase;
  text-decoration: none;
  vertical-align: 2px;
}

.label--primary,
.labelLink.label--primary {
  border-color: var(--k-signal);
  color: var(--k-signal);
}

:root .label--primary,
:root .labelLink.label--primary {
  color: var(--k-link);
  border-color: var(--k-link);
}

.input,
textarea.input,
select.input {
  box-sizing: border-box;
  width: 100%;
  min-height: 40px;
  padding: 8px 10px;
  border: 1px solid var(--k-line);
  border-radius: 2px;
  background: var(--k-surface-2);
  color: var(--k-ink);
  font: inherit;
  box-shadow: none;
}

textarea.input {
  min-height: 120px;
  resize: vertical;
}

.input:focus {
  border-color: var(--k-signal);
  outline: 2px solid #861f3240;
  outline-offset: 1px;
}

/* Notices */

.notice,
.blockMessage,
.blockStatus {
  background: var(--k-surface-2);
  border: 1px solid var(--k-line);
  border-left: 3px solid var(--k-signal);
  border-radius: 2px;
  color: var(--k-ink);
  box-shadow: none;
}

.notice-content,
.blockMessage {
  padding: 12px 14px;
}

.block--category {
  margin: 0 0 28px;
}

.p-body-content {
  counter-reset: kordon-cat;
}

.block--category {
  counter-increment: kordon-cat;
}

.block-container {
  background: var(--k-surface-2);
  border: 1px solid var(--k-line);
  border-radius: 2px;
  box-shadow: none;
  color: var(--k-ink);
}

.block--category > .block-container {
  background: transparent;
  border: 0;
}

.block-header,
.block-minorHeader {
  background: transparent;
  border-bottom: 1px solid var(--k-line);
  color: var(--k-ink);
}

.block--category .block-header {
  margin: 0 0 10px;
  padding: 0 0 8px;
  border-bottom: 0;
  font-size: 28px;
  line-height: 1.1;
}

.block--category .block-header a {
  color: var(--k-ink);
  text-decoration: none;
}

.block--category .block-header a:hover {
  color: var(--k-link);
}

.block--category .block-header a::before {
  content: counter(kordon-cat, decimal-leading-zero);
  margin-right: 12px;
  color: var(--k-signal);
  font-family: var(--k-mono), ui-monospace, monospace;
  font-size: 12px;
  font-weight: 500;
  letter-spacing: 0.12em;
  position: relative;
  top: -5px;
}

:root .block--category .block-header a::before {
  color: var(--k-link);
}

.block--category .block-desc {
  display: block;
  margin-top: 4px;
  color: var(--k-muted);
  font-family: var(--k-body), Arial, sans-serif;
  font-size: 14px;
  font-weight: 500;
  letter-spacing: 0;
}

.block--category .block-body {
  background: var(--k-surface-2);
  border: 1px solid var(--k-line);
  border-radius: 2px;
}

.block-minorHeader {
  padding: 14px 16px 10px;
  color: var(--k-bronze);
  font-family: var(--k-mono), ui-monospace, monospace;
  font-size: 11px;
  font-weight: 500;
  letter-spacing: 0.12em;
  text-transform: uppercase;
}

.block-row,
.block-footer {
  padding: 12px 16px;
}

.block-footer {
  border-top: 1px solid var(--k-line);
  color: var(--k-muted);
  font-size: 13px;
}

.block-filterBar,
.filterBar {
  background: var(--k-offset);
  border-bottom: 1px solid var(--k-line);
  color: var(--k-muted);
}

/* Nodes */

.node + .node {
  border-top: 1px solid var(--k-line);
}

.node-body {
  padding: 16px 18px;
}

.node-body:hover {
  background: var(--k-surface);
}

.node-icon {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 18px;
  height: 36px;
  border: 0;
  background: transparent;
  box-shadow: none;
}

.node-icon i {
  display: block;
  width: 2px;
  height: 16px;
  border: 0;
  border-radius: 2px;
  background: var(--k-line);
  font-size: 0;
  line-height: 0;
}

.node-icon i::before,
.node-icon svg {
  content: none;
}

.node--unread .node-icon {
  border: 0;
  box-shadow: none;
}

.node--unread .node-icon i {
  width: 3px;
  height: 22px;
  background: var(--k-signal);
}

:root .node-icon,
:root .node--unread .node-icon {
  background: transparent;
  border: 0;
  box-shadow: none;
}

:root .node--unread .node-icon i {
  background: var(--k-link);
}

.node--link .node-icon i {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: var(--k-bronze);
}

.node-stats .pairs dd {
  font-family: var(--k-display), Georgia, serif;
  font-size: 18px;
  font-weight: 600;
  letter-spacing: -0.03em;
  line-height: 1.1;
}

.node-title {
  margin: 0 0 3px;
  font-size: 21px;
  line-height: 1.2;
}

.node-title a {
  color: var(--k-ink);
  text-decoration: none;
}

.node-title a:hover {
  color: var(--k-link);
}

.node--unread .node-title a {
  font-weight: 650;
}

.node-description,
.node-extra,
.node-stats,
.node-meta,
.structItem-minor,
.u-muted {
  color: var(--k-muted);
}

.node-description {
  font-size: 14px;
  line-height: 1.45;
}

.node-stats .pairs dt,
.structItem-cell--meta .pairs dt,
.pairs dt {
  color: var(--k-faint);
  font-family: var(--k-mono), ui-monospace, monospace;
  font-size: 10px;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

.pairs dd {
  color: var(--k-ink);
  font-weight: 700;
}

.node-extra-title {
  color: var(--k-ink);
  font-weight: 650;
  text-decoration: none;
}

.node-extra-title:hover {
  color: var(--k-link);
}

/* Threads */

.structItem {
  border-top: 1px solid var(--k-line);
}

.structItem:hover {
  background: var(--k-surface);
}

.structItem-cell--latest {
  padding-left: 14px;
  border-left: 1px solid var(--k-line);
}

.structItem-cell--latest a,
.structItem-minor a,
.node-extra-row {
  color: var(--k-muted);
}

.structItem-cell--latest a:hover,
.structItem-minor a:hover {
  color: var(--k-link);
}

.structItem.is-sticky {
  background: #8a6a3d14;
}

:root .structItem.is-sticky {
  background: #e0c48a14;
}

.structItem-title {
  font-size: 18px;
  line-height: 1.3;
}

.structItem-title a {
  color: var(--k-ink);
  text-decoration: none;
}

.structItem-title a:hover,
.structItem.is-unread .structItem-title a {
  color: var(--k-ink);
}

.structItem-title a:hover {
  color: var(--k-link);
}

.structItem.is-unread .structItem-title a {
  font-weight: 650;
}

.structItem.is-unread .avatar {
  box-shadow: 0 0 0 2px var(--k-surface-2), 0 0 0 4px var(--k-signal);
}

/* Messages */

.block--messages .block-container,
.block--messages .message,
.message-inner {
  background: var(--k-surface-2);
}

.message + .message {
  border-top: 1px solid var(--k-line);
}

.message-cell--user {
  background: var(--k-bg);
  border-right: 1px solid var(--k-line);
}

.message-name,
.message-name a {
  color: var(--k-ink);
  font-size: 18px;
  text-decoration: none;
}

.message-userTitle {
  margin: 2px 0 8px;
  color: var(--k-muted);
  font-family: var(--k-body), Arial, sans-serif;
  font-size: 13px;
  font-weight: 500;
  letter-spacing: 0;
}

.userBanner {
  display: inline-block;
  margin: 4px 0;
  padding: 2px 7px;
  border-radius: 2px;
  background: var(--k-signal);
  color: var(--k-on-signal);
  font-family: var(--k-mono), ui-monospace, monospace;
  font-size: 10px;
  font-weight: 500;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

.username--staff,
.username--moderator {
  color: var(--k-signal);
}

:root .username--staff,
:root .username--moderator {
  color: var(--k-link);
}

.message-attribution {
  padding-bottom: 8px;
  border-bottom: 1px solid var(--k-line);
  color: var(--k-faint);
  font-family: var(--k-mono), ui-monospace, monospace;
  font-size: 11px;
  letter-spacing: 0.04em;
}

.message-attribution a {
  color: var(--k-muted);
  text-decoration: none;
}

.message-body,
.bbWrapper {
  color: var(--k-ink);
  font-size: 16.5px;
  line-height: 1.7;
}

.bbWrapper h2,
.bbWrapper h3 {
  margin: 1.2em 0 0.4em;
  line-height: 1.15;
}

.bbWrapper h2 { font-size: 26px; }
.bbWrapper h3 { font-size: 20px; }

.bbWrapper p { margin: 0 0 0.9em; }

.bbWrapper ul,
.bbWrapper ol {
  margin: 0 0 1em;
  padding-left: 1.2em;
}

.bbCodeBlock {
  margin: 0 0 1em;
  padding: 10px 14px;
  border: 0;
  border-left: 3px solid var(--k-bronze);
  border-radius: 0 2px 2px 0;
  background: var(--k-offset);
  color: var(--k-ink);
}

.bbCodeBlock-title {
  margin-bottom: 6px;
  color: var(--k-bronze);
  font-family: var(--k-mono), ui-monospace, monospace;
  font-size: 11px;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

.bbCodeBlock--code,
.bbCodeCode {
  border-left-color: var(--k-navy);
  font-family: var(--k-mono), ui-monospace, monospace;
  font-size: 13px;
}

:root .bbCodeBlock--code {
  border-left-color: var(--k-footer-link);
}

.message-signature {
  margin-top: 12px;
  padding-top: 8px;
  border-top: 1px solid var(--k-line);
  color: var(--k-faint);
  font-size: 13px;
}

.message-actionBar .actionBar-action {
  color: var(--k-muted);
  font-size: 13px;
  font-weight: 700;
  text-decoration: none;
}

.message-actionBar .actionBar-action:hover {
  color: var(--k-link);
}

.message--quickReply,
.fr-box,
.fr-toolbar,
.fr-element {
  background: var(--k-surface-2);
  border-color: var(--k-line);
  color: var(--k-ink);
}

.fr-toolbar {
  background: var(--k-offset);
}

/* Widgets */

.kordon-hotline {
  padding: 16px 16px 18px;
  background: var(--k-navy);
  border-color: var(--k-navy);
  border-top: 3px solid var(--k-footer-link);
  color: var(--k-on-navy);
}

.kordon-hotline-kicker {
  margin: 0 0 6px;
  color: var(--k-footer-link);
  font-family: var(--k-mono), ui-monospace, monospace;
  font-size: 11px;
  letter-spacing: 0.12em;
  text-transform: uppercase;
}

.kordon-hotline-number,
.kordon-hotline-number:hover {
  display: block;
  color: var(--k-on-navy);
  font-family: var(--k-display), Georgia, serif;
  font-size: 64px;
  font-weight: 600;
  letter-spacing: -0.04em;
  line-height: 0.9;
  text-decoration: none;
}

.kordon-hotline-text {
  margin: 8px 0 0;
  color: #f4f0e8d0;
  font-size: 14px;
  line-height: 1.5;
}

.contentRow-title a {
  color: var(--k-ink);
  font-weight: 700;
  text-decoration: none;
}

/* Bits */

.avatar {
  border-radius: 50%;
  overflow: hidden;
  background: var(--k-offset);
}

.avatar img {
  display: block;
  width: 100%;
  height: 100%;
  object-fit: cover;
  border-radius: 50%;
}

.pageNav {
  display: flex;
  align-items: center;
  gap: 4px;
}

.pageNav-page a,
.pageNav-jump {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-width: 32px;
  height: 32px;
  padding: 0 8px;
  border: 1px solid var(--k-line);
  border-radius: 2px;
  background: var(--k-surface-2);
  color: var(--k-ink);
  text-decoration: none;
  font-size: 13px;
}

.pageNav-page--current a,
.pageNav-page--current a:hover {
  background: var(--k-navy);
  border-color: var(--k-navy);
  color: var(--k-on-navy);
}

.menu-content,
.overlay-content,
.offCanvasMenu-content {
  background: var(--k-surface-2);
  color: var(--k-ink);
  border: 1px solid var(--k-line);
  border-radius: 2px;
  box-shadow: 0 18px 40px #16233a24;
}

.menu-linkRow,
.menu-linkRow:hover,
.offCanvasMenu-linkHolder a {
  color: var(--k-ink);
  text-decoration: none;
}

.menu-linkRow:hover,
.offCanvasMenu-linkHolder a:hover {
  background: var(--k-offset);
}

.offCanvasMenu-content {
  background: var(--k-navy);
  color: var(--k-on-navy);
  border: 0;
}

.offCanvasMenu-linkHolder a,
.offCanvasMenu-header {
  color: var(--k-on-navy);
}

.tooltip .tooltip-content {
  background: var(--k-navy);
  color: var(--k-on-navy);
  border-radius: 2px;
}

/* Footer */

.p-footer {
  background: var(--k-footer);
  color: #f4f0e8c7;
  border-top: 3px solid var(--k-signal);
}

.p-footer a {
  color: var(--k-footer-link);
  text-decoration: none;
}

.p-footer a:hover {
  color: var(--k-on-navy);
}

.p-footer-inner {
  padding-top: 28px;
  padding-bottom: 28px;
}

.p-footer-inner::before {
  content: "Независимый гражданский форум памяти и профилактики. Не является сайтом государственного органа. При угрозе — 112.";
  display: block;
  max-width: 70ch;
  margin-bottom: 16px;
  color: #f4f0e8;
  font-family: var(--k-display), Georgia, serif;
  font-size: 20px;
  line-height: 1.35;
  letter-spacing: -0.02em;
}

.p-footer-linkList {
  font-size: 14px;
}

.p-footer-copyright {
  margin-top: 14px;
  color: #f4f0e8a6;
  font-size: 12px;
}

.p-footer a[data-kordon-theme] {
  color: #f4f0e8b0;
}

.p-footer a[data-kordon-theme].is-active {
  color: var(--k-footer-link);
  box-shadow: inset 0 -2px 0 var(--k-signal);
}

/* Hotline and category rhythm on small screens */

@media (max-width: 700px) {
  .p-header::before {
    font-size: 10px;
    letter-spacing: 0.04em;
  }
  .p-header-logo--text a,
  .p-header-logo--image a {
    font-size: 28px;
  }
  .p-title-value {
    font-size: 30px;
  }
  .block--category .block-header {
    font-size: 24px;
  }
  .kordon-hotline-number {
    font-size: 52px;
  }
  .p-footer-inner::before {
    font-size: 17px;
  }
}

@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after {
    scroll-behavior: auto !important;
    transition: none !important;
    animation: none !important;
  }
}

@media (prefers-reduced-transparency: reduce) {
  body::before { display: none; }
}

@media print {
  body { border-top: 0; background: #fff; color: #000; }
  body::before,
  .p-nav,
  .p-sectionLinks,
  .p-footer,
  .p-staffBar,
  .message-actionBar,
  .p-title-pageAction { display: none !important; }
  .message-cell--user { border: 0; }
  a { color: #000; }
}
